from fastapi import FastAPI, Form
from fastapi.testclient import TestClient
from typing import Optional
import pytest

app = FastAPI()

@app.post("/test_empty_string")
async def test_empty_string(q: Optional[str] = Form(None)):
    return {"q": q}

client = TestClient(app)

def test_empty_string_is_none():
    # Sending an empty string for an optional Form field with default None
    # should result in the value being None, not "".
    response = client.post("/test_empty_string", data={"q": ""})
    assert response.status_code == 200
    assert response.json() == {"q": None}

def test_missing_field_is_none():
    # Not sending the field at all should also result in None.
    response = client.post("/test_empty_string", data={})
    assert response.status_code == 200
    assert response.json() == {"q": None}

def test_provided_value_is_kept():
    # Sending a non-empty string should be kept.
    response = client.post("/test_empty_string", data={"q": "hello"})
    assert response.status_code == 200
    assert response.json() == {"q": "hello"}

